import Foundation

enum L10n {
    static func text(_ key: String, language setting: AppLanguage) -> String {
        let language = resolved(setting)
        return diagnosticV2Override(for: key, language: language) ?? tables[language]?[key] ?? tables[.english]?[key] ?? key
    }

    /// Locale used by user-facing controls and date strings.
    /// For System language, follow the first preferred UI language rather than
    /// Locale.current alone so a Korean UI does not fall back to US-English dates.
    static func locale(for setting: AppLanguage) -> Locale {
        switch setting {
        case .korean: return Locale(identifier: "ko_KR")
        case .english: return Locale(identifier: "en_US")
        case .japanese: return Locale(identifier: "ja_JP")
        case .spanish: return Locale(identifier: "es_ES")
        case .system:
            if let preferred = Locale.preferredLanguages.first, !preferred.isEmpty {
                return Locale(identifier: preferred.replacingOccurrences(of: "-", with: "_"))
            }
            return .autoupdatingCurrent
        }
    }

    private static func resolved(_ setting: AppLanguage) -> AppLanguage {
        guard setting == .system else { return setting }
        let code = Locale.preferredLanguages.first?.lowercased() ?? "en"
        if code.hasPrefix("ko") { return .korean }
        if code.hasPrefix("ja") { return .japanese }
        if code.hasPrefix("es") { return .spanish }
        return .english
    }

    // Build 100 keeps the privacy guarantee visible before a report is created.
    // This is deliberately a value override, not a second localization table.
    private static func diagnosticV2Override(for key: String, language: AppLanguage) -> String? {
        guard key == "diagnosticReportWarningBody" else { return nil }
        switch language {
        case .korean:
            return "문제 해결에 필요한 최소 기술 상태만 포함합니다. Wi-Fi 이름, 위치 좌표, URL·도메인·IP 주소, 패킷 내용, 브라우징 기록, 사용자·개발자 식별자, 홈 경로, 과거 버전 이력은 포함하지 않습니다. 전송 전 내용을 확인해 주세요. 보고서는 오류 원인 확인과 업데이트 개선에만 사용하며, 제작자가 기술 내용을 분석할 때 AI를 이용할 수 있습니다."
        case .english:
            return "The report contains only the minimum technical states needed for troubleshooting. It does not include Wi-Fi names, location coordinates, URLs, domains, IP addresses, packet contents, browsing history, user or developer identifiers, home paths, or previous version history. Review it before sending. The report is used only to diagnose the issue and improve updates; the creator may use AI to help analyze technical details."
        case .japanese:
            return "トラブル解決に必要な最小限の技術状態のみを含みます。Wi-Fi 名、位置座標、URL・ドメイン・IP アドレス、パケット内容、閲覧履歴、ユーザー・開発者識別子、ホームパス、過去バージョン履歴は含みません。送信前に内容を確認してください。レポートは不具合の原因確認とアップデート改善にのみ使い、制作者が技術内容の解析に AI を利用する場合があります。"
        case .spanish:
            return "El informe contiene solo los estados técnicos mínimos necesarios para el diagnóstico. No incluye nombres de Wi-Fi, coordenadas de ubicación, URL, dominios, direcciones IP, contenido de paquetes, historial de navegación, identificadores de usuario o desarrollador, rutas personales ni historial de versiones anteriores. Revísalo antes de enviarlo. El informe se usa solo para diagnosticar el problema y mejorar actualizaciones; el creador puede usar IA para ayudar a analizar detalles técnicos."
        case .system:
            return nil
        }
    }

